  final String displayName;
  final String? appVersion;
  final int? protocolVersion;
  final DevicePlatform platform;
  final DeviceClass deviceClass;
  final String? osName;
  final String? osVersion;
  final String? model;
  final DeviceObservationProvenance provenance;
  final DeviceObservationTrust trust;
  final PlatformInt64 observedAtMs;
  final PlatformInt64? freshUntilMs;

  const DeviceProfile({
    required this.displayName,
    this.appVersion,
    this.protocolVersion,
    required this.platform,
    required this.deviceClass,
    this.osName,
    this.osVersion,
    this.model,
    required this.provenance,
    required this.trust,
    required this.observedAtMs,
    this.freshUntilMs,
  });

  @override
  int get hashCode =>
      displayName.hashCode ^
      appVersion.hashCode ^
      protocolVersion.hashCode ^
      platform.hashCode ^
      deviceClass.hashCode ^
      osName.hashCode ^
      osVersion.hashCode ^
      model.hashCode ^
      provenance.hashCode ^
      trust.hashCode ^
      observedAtMs.hashCode ^
      freshUntilMs.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is DeviceProfile &&
          runtimeType == other.runtimeType &&
          displayName == other.displayName &&
          appVersion == other.appVersion &&
          protocolVersion == other.protocolVersion &&
          platform == other.platform &&
          deviceClass == other.deviceClass &&
          osName == other.osName &&
          osVersion == other.osVersion &&
          model == other.model &&
          provenance == other.provenance &&
          trust == other.trust &&
          observedAtMs == other.observedAtMs &&
          freshUntilMs == other.freshUntilMs;
}

