/// Safe pairing state for ordinary Flutter UI. It deliberately has no invite
/// code, QR payload, SAS, network address, or peer identity value.
class PairingCeremony {
  final String ceremonyId;
  final String state;
  final BigInt? expiresInMs;
  final String? peerName;
  final String? failureMessage;

  const PairingCeremony({
    required this.ceremonyId,
    required this.state,
    this.expiresInMs,
    this.peerName,
    this.failureMessage,
  });

  @override
  int get hashCode =>
      ceremonyId.hashCode ^
      state.hashCode ^
      expiresInMs.hashCode ^
      peerName.hashCode ^
      failureMessage.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is PairingCeremony &&
          runtimeType == other.runtimeType &&
          ceremonyId == other.ceremonyId &&
          state == other.state &&
          expiresInMs == other.expiresInMs &&
          peerName == other.peerName &&
          failureMessage == other.failureMessage;
}

